def fpw(b, e, p):
    if e == 0:
        return 1
    r = fpw(b, e >> 1, p)
    return r * r * (b if e & 1 else 1) % p
def solve():
    a, p = map(int, input().split())
    phi, v = p - 1, p - 1
    for i in range(2, int(phi ** 0.5) + 2):
        if v % i == 0:
            while v % i == 0:
                v //= i
            if fpw(a, phi // i, p) == 1:
                print("No")
                return
    if v > 1:
        if fpw(a, phi // v, p) == 1:
            print("No")
            return
    print("Yes")
[solve() for _ in range(int(input()))]
